            args = sdscatprintf(args, "'%.*s' ", 128-(int)sdslen(args), (char*)c->argv[i]->ptr);
        *err = sdsnew(NULL);
        *err = sdscatprintf(*err, "unknown command '%.128s', with args beginning with: %s",
                            (char*)c->argv[0]->ptr, args);
        sdsfree(args);
    }
    /* Make sure there are no newlines in the string, otherwise invalid protocol
     * is emitted (The args come from the user, they may contain any character). */
    sdsmapchars(*err, "\r\n", "  ",  2);
    return 0;
}

/* Check if c->argc is valid for c->cmd, fills `err` with details in case it isn't.
 * Return 1 if valid. */
int commandCheckArity(client *c, sds *err) {
    if ((c->cmd->arity > 0 && c->cmd->arity != c->argc) ||
        (c->argc < -c->cmd->arity))
    {
        if (err) {
            *err = sdsnew(NULL);
            *err = sdscatprintf(*err, "wrong number of arguments for '%s' command", c->cmd->fullname);
        }
        return 0;
    }

    return 1;
}

/* If we're executing a script, try to extract a set of command flags from
 * it, in case it declared them. Note this is just an attempt, we don't yet
 * know the script command is well formed.*/
uint64_t getCommandFlags(client *c) {
    uint64_t cmd_flags = c->cmd->flags;

    if (c->cmd->proc == fcallCommand || c->cmd->proc == fcallroCommand) {
        cmd_flags = fcallGetCommandFlags(c, cmd_flags);
    } else if (c->cmd->proc == evalCommand || c->cmd->proc == evalRoCommand ||
               c->cmd->proc == evalShaCommand || c->cmd->proc == evalShaRoCommand)
    {
        cmd_flags = evalGetCommandFlags(c, cmd_flags);
    }

    return cmd_flags;
}

/* If this function gets called we already read a whole
 * command, arguments are in the client argv/argc fields.
 * processCommand() execute the command or prepare the
 * server for a bulk read from the client.
 *
 * If C_OK is returned the client is still alive and valid and
 * other operations can be performed by the caller. Otherwise
 * if C_ERR is returned the client was destroyed (i.e. after QUIT). */
int processCommand(client *c) {
    if (!scriptIsTimedout()) {
        /* Both EXEC and scripts call call() directly so there should be
         * no way in_exec or scriptIsRunning() is 1.
         * That is unless lua_timedout, in which case client may run
         * some commands. */
        serverAssert(!server.in_exec);
        serverAssert(!scriptIsRunning());
    }

    moduleCallCommandFilters(c);

state.output:
    if (numkeys_obj == NULL) {
        numkeys = 0;
        parsed_numkeys = 1;
    } else {
        serverAssertWithInfo(NULL, numkeys_obj, numkeys_obj->type == OBJ_STRING);
        if (sdsEncodedObject(numkeys_obj)) {
            if (string2ll(numkeys_obj->ptr, sdslen(numkeys_obj->ptr), &numkeys) == 0) {
                addReplyError(c, "Bad number of keys provided");
            } else {
                parsed_numkeys = 1;
            }
        } else if (numkeys_obj->encoding == OBJ_ENCODING_INT) {
            numkeys = (long)numkeys_obj->ptr;
            parsed_numkeys = 1;
        } else {
            serverPanic("Unknown string encoding");
        }
    }

    if (parsed_numkeys) {
        if (numkeys > (c->argc - 3)) {
            addReplyError(c, "Number of keys can't be greater than number of args");
        } else if (numkeys < 0) {
            addReplyError(c, "Number of keys can't be negative");
        } else {
            serverAssert(!curr_run_ctx);
            if (!has_eval_compat) {
                if (has_no_cluster && server.cluster_enabled) {
                    addReplyError(caller, "Can not run script on cluster, 'no-cluster' flag is set.");
                } else if (running_stale && !has_allow_stale) {
                    addReplyError(caller, "-MASTERDOWN Link with MASTER is down, "
                                     "replica-serve-stale-data is set to 'no' "
                                     "and 'allow-stale' flag is not set on the script.");
                } else {
                    if (!has_no_writes) {
                        if (server.masterhost && server.repl_slave_ro && !obey_client) {
                            addReplyError(caller, "-READONLY Can not run script with write flag on readonly replica");
                            write_blocked = 1;
                        } else {
                            if (server.stop_writes_on_bgsave_err &&
                                server.saveparamslen > 0 &&
                                server.lastbgsave_status == C_ERR)
                            {
                                deny_write_type = DISK_ERROR_TYPE_RDB;
                            }
                                            if (deny_write_type == DISK_ERROR_TYPE_NONE && server.aof_state != AOF_OFF) {
                                atomicGet(server.aof_bio_fsync_status, aof_bio_fsync_status);
                                if (server.aof_last_write_status == C_ERR) {
                                    deny_write_type = DISK_ERROR_TYPE_AOF;
                                } else if (aof_bio_fsync_status == C_ERR) {
                                    atomicGet(server.aof_bio_fsync_errno, server.aof_last_write_errno);
                                    deny_write_type = DISK_ERROR_TYPE_AOF;
                                }
                            }
                            if (deny_write_type != DISK_ERROR_TYPE_NONE && !obey_client) {
                                write_blocked = 1;
                                if (deny_write_type == DISK_ERROR_TYPE_RDB) {
                                    addReplyError(caller, "-MISCONF Redis is configured to save RDB snapshots, "
                                                     "but it's currently unable to persist to disk. "
                                                     "Writable scripts are blocked. Use 'no-writes' flag for read only scripts.");
                                } else {
                                    addReplyErrorFormat(caller, "-MISCONF Redis is configured to persist data to AOF, "
                                                           "but it's currently unable to persist to disk. "
                                                           "Writable scripts are blocked. Use 'no-writes' flag for read only scripts. "
                                                           "AOF error: %s", strerror(server.aof_last_write_errno));
                                }
                            } else if (ro) {
                                addReplyError(caller, "Can not execute a script with write flag using *_ro command.");
                                write_blocked = 1;
                            } else {
                                replica_lag_window = server.repl_min_slaves_max_lag;
                                replica_needed = server.repl_min_slaves_to_write;
                                replica_good = server.repl_good_slaves_count;
                                if (server.masterhost) {
                                    replicas_ok = 1;
                                } else if (!replica_lag_window) {
                                    replicas_ok = 1;
                                } else if (!replica_needed) {
                                    replicas_ok = 1;
                                } else if (replica_good >= replica_needed) {
                                    replicas_ok = 1;
                                } else {
                                    replicas_ok = 0;
                                }
                                if (!replicas_ok) {
                                    addReplyErrorObject(caller, shared.noreplicaserr);
                                    write_blocked = 1;
                                }
                            }
                        }
                    }
                    if (!write_blocked) {
                        if (!client_allow_oom && server.pre_command_oom_state && server.maxmemory &&
                            !(has_allow_oom || has_no_writes))
                        {
                            addReplyError(caller, "-OOM allow-oom flag is not set on the script, "
                                                  "can not run it when used memory > 'maxmemory'");
                        } else {
                            prepared = 1;
                        }
                    }
                }
            } else {
                if (running_stale) {
                    addReplyErrorObject(caller, shared.masterdownerr);
                } else {
                    prepared = 1;
                }
            }

            if (prepared) {
                funcname = fi->name;
                compiled_function = fi->function;
                engine_ctx = engine->engine_ctx;
                run_ctx.c = engine_client;
                run_ctx.original_client = caller;
                run_ctx.funcname = funcname;
                script_client = run_ctx.c;
                curr_client = run_ctx.original_client;
                server.script_caller = curr_client;
                dbid = curr_client->db->id;
                if (dbid >= 0 && dbid < server.dbnum) {
                    script_client->db = &server.db[dbid];
                }
                script_client->resp = 2;
                if (curr_client->flags & CLIENT_MULTI) {
                    script_client->flags |= CLIENT_MULTI;
                }
                run_ctx.start_time = getMonotonicUs();
                run_ctx.snapshot_time = mstime();
                run_ctx.flags = 0;
                run_ctx.repl_flags = PROPAGATE_AOF | PROPAGATE_REPL;
                if (ro) {
                    run_ctx.flags |= SCRIPT_READ_ONLY;
                } else if (!has_eval_compat && has_no_writes) {
                    run_ctx.flags |= SCRIPT_READ_ONLY;
                }
                if (client_allow_oom) {
                    run_ctx.flags |= SCRIPT_ALLOW_OOM;
                } else if (!has_eval_compat && has_allow_oom) {
                    run_ctx.flags |= SCRIPT_ALLOW_OOM;
                }
                if (has_eval_compat) {
                    run_ctx.flags |= SCRIPT_ALLOW_CROSS_SLOT;
                } else if (has_allow_cross_slot) {
                    run_ctx.flags |= SCRIPT_ALLOW_CROSS_SLOT;
                }
                curr_run_ctx = &run_ctx;
                keys = c->argv + 3;
                nkeys = (size_t) numkeys;
                args = c->argv + 3 + numkeys;
                nargs = (size_t) (c->argc - 3 - numkeys);
                engine->call(&run_ctx, engine_ctx, compiled_function, keys, nkeys, args, nargs);
                serverAssert(curr_run_ctx);
                run_ctx.c->flags &= ~CLIENT_MULTI;
                server.script_caller = NULL;
                if (curr_run_ctx && (curr_run_ctx->flags & SCRIPT_TIMEDOUT)) {
                    serverAssert(curr_run_ctx == &run_ctx);
                    run_ctx.flags &= ~SCRIPT_TIMEDOUT;
                    blockingOperationEnds();
                    if (server.masterhost) {
                        if (server.master) {
                            queueClientForReprocessing(server.master);
                        }
                    }
                    timeout_client = run_ctx.original_client;
                    if (timeout_client->flags & CLIENT_PROTECTED) {
                        timeout_client->flags &= ~CLIENT_PROTECTED;
                        if (timeout_client->conn) {
                            connSetReadHandler(timeout_client->conn, readQueryFromClient);
                            pending_replies = clientHasPendingReplies(timeout_client);
                            if (pending_replies) {
                                putClientInPendingWriteQueue(timeout_client);
                            }
                        }
                    }
                }
                preventCommandPropagation(run_ctx.original_client);
                curr_run_ctx = NULL;
            }
        }
    }
}

